    const a0 = sx > 0 ? Math.PI : 0, a1 = sz > 0 ? -Math.PI / 2 : Math.PI / 2; let da = a1 - a0; while (da > Math.PI) da -= 2 * Math.PI; while (da < -Math.PI) da += 2 * Math.PI;
    for (let i = 0; i <= 10; i++) { const t = i / 10, a = a0 + da * t; pts.push([cx + Math.cos(a) * R0, cz + Math.sin(a) * R0, 22 - 10 * t]); }
